t.script:
document.addEventListener("DOMContentLoaded", function () {

    // =================================================
    // ELEMENTS HTML
    // =================================================

    const input =
        document.getElementById("plant-image");

    const fileName =
        document.getElementById("selected-file");

    const previewContainer =
        document.getElementById(
            "image-preview-container"
        );

    const preview =
        document.getElementById("image-preview");

    const analysisAction =
        document.getElementById("analysis-action");

    const startAnalysis =
        document.getElementById("start-analysis");

    const analysisLoading =
        document.getElementById("analysis-loading");

    const analysisResult =
        document.getElementById("analysis-result");

    const aiResult =
        document.getElementById("ai-result");

    const aiConfidence =
        document.getElementById("ai-confidence");

    const aiRecommendations =
        document.getElementById(
            "ai-recommendations"
        );


    // =================================================
    // IDENTIFIANT DU DIAGNOSTIC ODOO
    // =================================================

    let diagnosticId = null;


    // =================================================
    // VERIFICATION DE LA PAGE
    // =================================================

    if (!input) {
        return;
    }


    // =================================================
    // SELECTION DE L'IMAGE
    // =================================================

    input.addEventListener(
        "change",
        async function () {

            const file =
                input.files[0];


            // =================================================
            // AUCUNE IMAGE
            // =================================================

            if (!file) {

                fileName.textContent =
                    "Aucune image sélectionnée";

                previewContainer.style.display =
                    "none";

                analysisAction.style.display =
                    "none";

                if (analysisLoading) {

                    analysisLoading.style.display =
                        "none";

                }

                if (analysisResult) {

                    analysisResult.style.display =
                        "none";

                }

                preview.src = "";

                diagnosticId = null;

                return;
            }


            // =================================================
            // REINITIALISATION DU RESULTAT
            // =================================================

            diagnosticId = null;

            if (analysisLoading) {

                analysisLoading.style.display =
                    "none";

            }

            if (analysisResult) {

                analysisResult.style.display =
                    "none";

            }

            if (startAnalysis) {

                startAnalysis.disabled =
                    false;

                startAnalysis.textContent =
                    "🔎 Lancer l'analyse";

            }


            // =================================================
            // APERCU LOCAL DE L'IMAGE
            // =================================================

            fileName.textContent =
                "Image sélectionnée";


            const imageUrl =
                URL.createObjectURL(file);

            preview.src =
                imageUrl;

            previewContainer.style.display =
                "block";


            // =================================================
            // AFFICHAGE DU BOUTON D'ANALYSE
            // =================================================

            analysisAction.style.display =
                "block";


            // =================================================
            // PREPARATION DE L'ENVOI
            // =================================================

            const formData =
                new FormData();

            formData.append(
                "plant_image",
                file
            );


            // =================================================
            // ENVOI DE L'IMAGE VERS ODOO
            // =================================================

            try {

                const response =
                    await fetch(
                        "/diagnostic/upload",
                        {
                            method: "POST",
                            body: formData
                        }
                    );


                const result =
                    await response.json();


                console.log(
                    "Réponse Odoo :",
                    result
                );


                // =================================================
                // DIAGNOSTIC CREE
                // =================================================

                if (result.success) {

                    diagnosticId =
                        result.diagnostic_id;


                    fileName.textContent =
                        "Image envoyée : "
                        + result.filename;


                    console.log(
                        "Diagnostic ID :",
                        diagnosticId
                    );


                } else {

                    diagnosticId = null;

                    fileName.textContent =
                        result.message;

                    analysisAction.style.display =
                        "none";

                }


            } catch (error) {

                console.error(
                    "Erreur lors de l'envoi de l'image :",
                    error
                );


                diagnosticId = null;

                fileName.textContent =
                    "Erreur lors de l'envoi de l'image";

                analysisAction.style.display =
                    "none";

            }

        }
    );


    // =================================================
    // LANCEMENT DE L'ANALYSE
    // =================================================

    if (startAnalysis) {

        startAnalysis.addEventListener(
            "click",
            async function () {


                // =================================================
                // VERIFICATION DU DIAGNOSTIC
                // =================================================

                if (!diagnosticId) {

                    console.error(
                        "Aucun diagnostic disponible"
                    );

                    fileName.textContent =
                        "Veuillez sélectionner une image";

                    return;
                }


                // =================================================
                // DESACTIVATION DU BOUTON
                // =================================================

                startAnalysis.disabled =
                    true;

                startAnalysis.textContent =
                    "⏳ Analyse en cours...";


                // =================================================
                // AFFICHAGE DU CHARGEMENT
                // =================================================

                if (analysisLoading) {

                    analysisLoading.style.display =
                        "block";

                }


                // =================================================
                // PREPARATION DE LA REQUETE
                // =================================================

                const formData =
                    new FormData();

                formData.append(
                    "diagnostic_id",
                    diagnosticId
                );


                // =================================================
                // APPEL DE LA ROUTE ODOO
                // =================================================

                try {

                    const response =
                        await fetch(
                            "/diagnostic/start",
                            {
                                method: "POST",
                                body: formData
                            }
                        );


                    const result =
                        await response.json();


                    console.log(
                        "Réponse analyse :",
                        result
                    );


                    // =================================================
                    // ANALYSE TERMINEE
                    // =================================================

                    if (result.success) {

                        // =================================================
                        // ATTENTE MINIMUM POUR LE CHARGEMENT
                        // =================================================

                        await new Promise(
                            resolve =>
                                setTimeout(
                                    resolve,
                                    1500
                                )
                        );


                        // =================================================
                        // MASQUER LE CHARGEMENT
                        // =================================================

                        if (analysisLoading) {

                            analysisLoading.style.display =
                                "none";

                        }


                        // =================================================
                        // AFFICHAGE DE L'ETAT
                        // =================================================

                        fileName.textContent =
                            "✅ " + result.state_label;


                        startAnalysis.textContent =
                            "✅ Analyse terminée";


                        // =================================================
                        // AFFICHAGE DU RESULTAT
                        // =================================================

                        if (analysisResult) {

                            analysisResult.style.display =
                                "block";

                        }


                        if (aiResult) {

                            aiResult.textContent =
                                result.ai_result ||
                                "Aucun résultat disponible";

                        }


                        if (aiConfidence) {

                            const confidence =
                                Number(
                                    result.ai_confidence || 0
                                ) * 100;

                            aiConfidence.textContent =
                                confidence.toFixed(0)
                                + " %";

                        }


                        if (aiRecommendations) {

                            aiRecommendations.textContent =
                                result.recommendations ||
                                "Aucune recommandation disponible";

                        }


                        // =================================================
                        // BOUTON
                        // =================================================

                        startAnalysis.disabled =
                            true;


                        // =================================================
                        // CONSOLE
                        // =================================================

                        console.log(
                            "État du diagnostic :",
                            result.state
                        );

                        console.log(
                            "Résultat IA :",
                            result.ai_result
                        );

                        console.log(
                            "Confiance IA :",
                            result.ai_confidence
                        );

                        console.log(
                            "Recommandations :",
                            result.recommendations
                        );


                    } else {

                        // =================================================
                        // MASQUER LE CHARGEMENT EN CAS D'ECHEC
                        // =================================================

                        if (analysisLoading) {

                            analysisLoading.style.display =
                                "none";

                        }


                        fileName.textContent =
                            result.message;

                        startAnalysis.disabled =
                            false;

                        startAnalysis.textContent =
                            "🔎 Lancer l'analyse";

                    }


                } catch (error) {

                    // =================================================
                    // MASQUER LE CHARGEMENT EN CAS D'ERREUR
                    // =================================================

                    if (analysisLoading) {

                        analysisLoading.style.display =
                            "none";

                    }


                    console.error(
                        "Erreur lors du lancement de l'analyse :",
                        error
                    );


                    fileName.textContent =
                        "Erreur lors du lancement de l'analyse";


                    startAnalysis.disabled =
                        false;

                    startAnalysis.textContent =
                        "🔎 Lancer l'analyse";

                }

            }
        );

    }

});
